function afficherRecherche(q) {
  const box = document.getElementById('recherche-results');
  if (!box) return;
  if (!q || q.length < 2) { box.classList.add('hidden'); return; }
  const needle = q.toLowerCase();
  const found = SITE_INDEX.filter(e => (e.t + ' ' + e.m).includes(needle)).slice(0, 6);
  box.innerHTML = found.length
    ? found.map(e => `<a href="${e.u}">${e.t}</a>`).join('')
    : '<span class="recherche-vide">Aucune page ne correspond… essayez « TVA », « dividendes », « conjoint »</span>';
  box.classList.remove('hidden');
}
document.addEventListener('click', function (ev) {
  const box = document.getElementById('recherche-results');
  if (box && !ev.target.closest('.recherche-wrap')) box.classList.add('hidden');
});